/** Issue #94: updating the device in place from Settings. */
export interface ReqCheckUpdate {
}

export interface UpdateRelease {
  version: number;
  /**
   * Issue #183: "minor", "major" or "critical", and its "major.minor"
   * label (empty for releases from before labels, which show as builds).
   */
  kind: string;
  label: string;
  /**
   * Named "summary" rather than "description": SwiftProtobuf renames a
   * field called description to description_p, because it would collide
   * with CustomStringConvertible - and every client would then be reading
   * an oddly-named field for no reason.
   */
  summary: string;
}

export interface RespUpdateInfo {
  currentVersion: number;
  latestVersion: number;
  /**
   * The releases this device has yet to apply, oldest first - what makes
   * the update incremental rather than a reinstall.
   */
  pending: UpdateRelease[];
  /**
   * "idle", "running", "done", "failed" or "uptodate", plus whatever the
   * runner last reported. Survives the restart an update performs, since
   * the runner writes it to disk rather than holding it in memory.
   */
  state: string;
  message: string;
  lastUpdated: string;
  /**
   * Set when the manifest itself couldn't be reached, which is different
   * from "no updates": one means try again later, the other means there
   * is nothing to do.
   */
  checkError: string;
  /** Issue #183: the installed version's label ("1.1"; empty before labels). */
  currentLabel: string;
  latestLabel: string;
  /**
   * The device runs from the container image (docker/, OTC_CONTAINER): it
   * can't update itself, its owner pulls the new image on the server, and
   * message says how. Clients show that message instead of the Update
   * button. Pending lists only releases whose image is already published.
   */
  container: boolean;
}

/**
 * Starts the update and answers immediately - it takes minutes and ends
 * by restarting this very process, so there is nothing to wait for. Poll
 * ReqCheckUpdate for progress.
 */
export interface ReqApplyUpdate {
}

/**
 * Settings > Restart device: the owner of the primary instance restarts
 * the whole machine (systemctl reboot, run as root by otc-reboot.service -
 * see scripts/device-runner/). Supervised per-user instances (issue #82)
 * are refused. Answers RestartingDevice before the restart begins; the
 * connection then drops and the apps reconnect once the device is back.
 * A device before this release answers error_code "unknown_payload".
 */
export interface RestartDevice {
}

export interface RestartingDevice {
  /** About how long the device is expected to be unreachable, in seconds. */
  expectedSeconds: number;
}

/**
 * Settings › Storage: erase a disk Status.mirror_candidates lists and add
 * it to the mirror as its second disk; the mirror then copies every file
 * onto it. The owner of the primary instance only: a user's instance gets
 * an error without a code, a container dev.err.not_in_container, a demo
 * device error_code "demo", devices before it "unknown_payload".
 * Answers the generic Ack at once: ok once the request is handed to the
 * root watcher (scripts/raid_watch.py), which checks everything again
 * before it erases anything; the copy then shows in Status (raid_state
 * RaidSyncing, raid_sync_percent), and an Alert says why when the watcher
 * didn't use the disk. Refused before anything is asked - Ack ok false
 * with code and error_msg, both also on the envelope (error_code,
 * error_message): "not_candidate" (no such disk is offered now: unplugged,
 * or already added), "not_degraded" (the mirror has both its disks, or a
 * replacement is being copied onto), "busy" (another disk was just asked
 * for and the watcher hasn't taken it yet).
 */
export interface UseMirrorDisk {
  /** MirrorDiskCandidate.id. */
  disk: string;
}

/**
 * Issue #80: reaching the device over Tailscale Funnel instead of the
 * bridge. Offered at first setup; see the limitations spelled out there.
 */
export interface ReqSetupTailscale {
  /**
   * Optional. With a pre-shared auth key the whole setup is
   * non-interactive; without one, Tailscale needs a human to authorise
   * the node and the answer carries the URL to do that on. In the clear:
   * what clients sent before auth_key_sealed (still read when that is
   * empty).
   */
  authKey: string;
  /**
   * False turns Funnel back off. The node stays in the tailnet - leaving
   * that is the owner's business, not something this switch should
   * decide for them.
   */
  enable: boolean;
  /**
   * auth_key sealed with RSA-OAEP-SHA-256 under this connection's
   * GetPubKey key, as ChangeKey's keys are (issue #2): the bridge relays
   * this request. When set, auth_key is ignored.
   */
  authKeySealed: Uint8Array;
}

export interface ReqGetTailscaleStatus {
}

/**
 * Issue #145: turning on the bridge after a setup that went without it.
 * Owner-device only, like the Tailscale switch above. The flow: sign in to
 * an Off The Cloud account (ReqBridgeSignIn, or a provider sign-in in the
 * browser that comes back with a setup code), then ReqEnableBridge with a
 * name - the device reserves it and restarts itself on the bridge.
 */
export interface ReqGetBridgeAccess {
}

export interface RespBridgeAccess {
  /** The device is on the bridge (it has a bridge configured). */
  enabled: boolean;
  /** Its address there, e.g. "cala.off-the.cloud"; empty when not enabled. */
  domain: string;
  /** The bridge a local-only device would join, e.g. "off-the.cloud". */
  bridge: string;
  /** A name is reserved and the device is restarting onto the bridge. */
  pending: boolean;
  /** Why the last attempt to switch it on failed, if it did. */
  error: string;
  /**
   * The account sign-ins the bridge offers besides email ("apple",
   * "google"), for the web app's buttons.
   */
  providers: string[];
  /**
   * Issue #182: why a device is local-only after having been on the
   * bridge ("left": the owner switched it off; "released": the bridge no
   * longer knew its name - the account was deleted or the name given
   * back). Empty otherwise.
   */
  leftReason: string;
  /**
   * The device's address on the home network ("192.168.1.20:8080"), for
   * a client to reach it by once it is local-only: .local names don't
   * resolve everywhere (Android). Empty when it can't be worked out.
   */
  localAddress: string;
}

/**
 * Issue #182: an owner's client asks the device to leave the bridge and
 * work locally (at http://otc.local:8080), as if set up without it. The
 * device gives its name back (BridgeReleaseDomain) and restarts local-only.
 * Answers with RespBridgeAccess (pending while it restarts).
 */
export interface ReqDisableBridge {
}

/**
 * Either email + password, or a setup code (from the bridge's account
 * page, or handed back by a provider sign-in). Answers with
 * RespBridgeSignedIn.
 */
export interface ReqBridgeSignIn {
  email: string;
  /**
   * In the clear: what clients sent before password_sealed (still read
   * when that is empty).
   */
  password: string;
  setupCode: string;
  /**
   * The account password sealed with RSA-OAEP-SHA-256 under this
   * connection's GetPubKey key, as ChangeKey's keys are (issue #2): the
   * bridge relays this request. When set, password is ignored.
   */
  passwordSealed: Uint8Array;
}

export interface RespBridgeSignedIn {
  /** Short-lived; only good for ReqEnableBridge. */
  setupToken: string;
  email: string;
}

/** Answers with RespBridgeAccess (pending), then the device restarts. */
